// Synchronous raw evidence only. No process binding, live entry, prerequisite or proof acceptance.
// The caller must provide the exact reviewed synchronous operations and all external gates.
import assert from 'node:assert/strict';
import path from 'node:path';
import {types} from 'node:util';

const DOCKER_CONFIG='/tmp/lexlean-r4-docker-config-20261021';
const DOCKER_HOST='unix:///Users/casey.allard/.colima/lexlean-r4/docker.sock';
function plain(value){
 assert(value!==null&&typeof value==='object'&&!types.isProxy(value),'Plain data required');
 assert([null,Object.prototype].includes(Object.getPrototypeOf(value)),'Plain prototype required');
 const descriptors=Object.getOwnPropertyDescriptors(value);
 for(const d of Object.values(descriptors))assert(Object.hasOwn(d,'value'),'Accessors are forbidden');
 return descriptors;
}
function array(value){
 assert(!types.isProxy(value)&&Array.isArray(value),'Plain array required');
 assert(Object.getPrototypeOf(value)===Array.prototype);
 const d=Object.getOwnPropertyDescriptors(value);
 for(const x of Object.values(d))assert(Object.hasOwn(x,'value'),'Array accessors are forbidden');
 assert.equal(Object.keys(d).length,value.length+1,'Dense array without extra fields required');
 return Array.from({length:value.length},(_,i)=>{assert(Object.hasOwn(d,String(i)));return d[i].value;});
}
function safe(label){assert(typeof label==='string'&&label.length&&!path.isAbsolute(label)&&!label.includes('\\')&&label.split('/').every(p=>p&&p!=='.'&&p!=='..'),'Safe relative label required');}
function data(d,key){assert(Object.hasOwn(d,key),'Missing field '+key);return d[key].value;}
function snapshot(owner,invocation,ops){
 const od=plain(owner),id=plain(invocation),op=plain(ops);
 assert(Object.isFrozen(owner)&&Object.isFrozen(invocation),'Fixed descriptors required');
 for(const name of ['checked','lstatSync','mkdirSync','openSync','closeSync','writeFileSync','readFileSync','linkSync','sha','now','pins','spawnSync']){
  const f=data(op,name);assert(typeof f==='function'&&!types.isProxy(f)&&!types.isAsyncFunction(f),'Synchronous operation required: '+name);
 }
 if(Object.hasOwn(op,'serialize'))assert(typeof data(op,'serialize')==='function'&&!types.isProxy(data(op,'serialize'))&&!types.isAsyncFunction(data(op,'serialize')));
 assert.equal(data(od,'localExclusiveLink'),true);assert.equal(data(op,'localExclusiveLink'),true,'Local exclusive hardlink required');
 const root=data(od,'path');assert(typeof root==='string'&&path.isAbsolute(root)&&path.normalize(root)===root);
 assert(Number.isSafeInteger(data(od,'dev'))&&Number.isSafeInteger(data(od,'ino')));
 assert.equal(data(id,'executable'),'docker');
 const args=array(data(id,'args'));assert(Object.isFrozen(data(id,'args')));assert(args.length&&args.every(x=>typeof x==='string'&&!x.includes('\0')));
 const containerId=data(id,'containerId');assert(typeof containerId==='string'&&containerId.length);assert(args.some(x=>x===containerId||x.startsWith(containerId+':')),'Fixed container missing from invocation');
 const environment=data(id,'environment'),ed=plain(environment);assert(Object.isFrozen(environment));
 const env=Object.fromEntries(Object.entries(ed).map(([k,d])=>{assert(typeof d.value==='string');return[k,d.value];}));
 assert.equal(env.DOCKER_CONFIG,DOCKER_CONFIG);assert.equal(env.DOCKER_HOST,DOCKER_HOST);
 // Snapshot only trusted synchronous functions; no later access to caller descriptors.
 const functions=Object.fromEntries(Object.entries(op).map(([k,d])=>[k,d.value]));
 return{root,dev:data(od,'dev'),ino:data(od,'ino'),args:Object.freeze(args),env:Object.freeze(env),ops:Object.freeze(functions)};
}
function describe(cause){
 if(cause===undefined)return{type:'undefined'};
 if(cause===null)return{type:'null'};
 if(['string','boolean'].includes(typeof cause))return{type:typeof cause,value:cause};
 if(typeof cause==='number')return{type:'number',value:Number.isFinite(cause)?cause:String(cause)};
 if(typeof cause==='bigint')return{type:'bigint',value:String(cause)};
 if((typeof cause==='object'||typeof cause==='function')&&!types.isProxy(cause)&&types.isNativeError(cause)){
  // Descriptor reads do not invoke Error.message/name/stack accessors or custom serializers.
  const ds=Object.getOwnPropertyDescriptors(cause),fields={};
  for(const key of ['name','message','code'])if(Object.hasOwn(ds,key)){
   const d=ds[key];fields[key]=Object.hasOwn(d,'value')&&['string','number','boolean'].includes(typeof d.value)?{type:typeof d.value,value:d.value}:{type:'opaque-or-accessor'};
  }
  return{type:'Error',fields};
 }
 return{type:'opaque'};
}
export function recordSync(owner,invocation,label,operations){
 const s=snapshot(owner,invocation,operations),o=s.ops;safe(label);
 const errors=[],phases=[];let ownedDir=false,dirIdentity,started,ended,result,stdout,stderr,stdoutHash,stderrHash;
 const streams=[{name:'stdout',acquired:false},{name:'stderr',acquired:false}];
 const fail=(phase,cause)=>{phases.push(phase);errors.push(cause);};
 const attempt=(phase,fn)=>{try{return{ok:true,value:fn()};}catch(cause){fail(phase,cause);return{ok:false};}};
 const identity=(p,kind)=>{o.checked(p,kind);const st=o.lstatSync(p);return{dev:st.dev,ino:st.ino};};
 const same=(p,kind,id)=>assert.deepEqual(identity(p,kind),id,'Owned path identity changed');
 const absent=p=>{try{o.lstatSync(p);}catch(e){
   // Do not invoke an arbitrary thrown code getter.
   if(e!==null&&typeof e==='object'&&!types.isProxy(e)){const d=Object.getOwnPropertyDescriptor(e,'code');if(d&&Object.hasOwn(d,'value')&&d.value==='ENOENT')return;}
   throw e;
  }throw new Error('Preserve existing path '+p);};
 const dir=s.root+'/'+label;
 const setup=attempt('setup',()=>{
  o.pins();same(s.root,'directory',{dev:s.dev,ino:s.ino});
  let parent=s.root;
  for(const part of label.split('/').slice(0,-1)){
   parent+='/'+part;let missing=false;
   try{o.checked(parent,'directory');}catch(e){const d=e&&typeof e==='object'&&!types.isProxy(e)?Object.getOwnPropertyDescriptor(e,'code'):null;if(d&&d.value==='ENOENT')missing=true;else throw e;}
   if(missing)o.mkdirSync(parent,{mode:0o700});
   assert.equal(identity(parent,'directory').dev,s.dev);
  }
  absent(dir);o.mkdirSync(dir,{mode:0o700});dirIdentity=identity(dir,'directory');assert.equal(dirIdentity.dev,s.dev);ownedDir=true;
 });
 if(setup.ok){
  for(const stream of streams){if(errors.length)break;const opened=attempt('open.'+stream.name,()=>o.openSync(dir+'/'+stream.name,'wx',0o600));if(opened.ok){stream.fd=opened.value;stream.acquired=true;}}
  if(errors.length===0){
   const start=attempt('clock.start',()=>{const value=o.now();assert(typeof value==='string'&&Number.isFinite(Date.parse(value)));return value;});
   if(start.ok){
    started=start.value;let threw=false,thrown,endResult;
    try{result=o.spawnSync('docker',s.args,{env:s.env,stdio:['ignore',streams[0].fd,streams[1].fd]});}catch(cause){threw=true;thrown=cause;}
    // Capture end time immediately; report dispatch primary first even if both fail.
    try{const value=o.now();assert(typeof value==='string'&&Number.isFinite(Date.parse(value)));assert(Date.parse(value)>=Date.parse(started));endResult={ok:true,value};}catch(cause){endResult={ok:false,cause};}
    if(threw)fail('dispatch',thrown);
    else attempt('process.result',()=>{
     const d=plain(result);
     if(Object.hasOwn(d,'error')){fail('dispatch.error',d.error.value);return;}
     const status=data(d,'status'),signal=data(d,'signal');
     assert((Number.isSafeInteger(status)&&status>=0&&status<=255&&signal===null)||(status===null&&typeof signal==='string'&&signal.length>0),'Malformed process status/signal');
     result={status,signal};
    });
    if(endResult.ok)ended=endResult.value;else fail('clock.end',endResult.cause);
   }
  }
 }
 // Every acquired descriptor gets one independent close attempt, including fd0.
 for(const stream of streams)if(stream.acquired)attempt('close.'+stream.name,()=>o.closeSync(stream.fd));
 for(const stream of streams)if(stream.acquired){
  const got=attempt('read.'+stream.name,()=>{o.checked(dir+'/'+stream.name);const b=o.readFileSync(dir+'/'+stream.name);assert(Buffer.isBuffer(b));return b;});
  if(got.ok){stream.bytes=got.value;const hashed=attempt('hash.'+stream.name,()=>{const h=o.sha(got.value);assert(typeof h==='string'&&/^[a-f0-9]{64}$/.test(h));return h;});if(hashed.ok)stream.hash=hashed.value;}
 }
 stdout=streams[0].bytes;stderr=streams[1].bytes;stdoutHash=streams[0].hash;stderrHash=streams[1].hash;
 // Small local persistence helper; no retries, deletion, overwrite or deferred work.
 function persist(name,bytes,prefix){
  const p=dir+'/'+name;let fd,acquired=false;
  const opened=attempt(prefix+'.open',()=>{same(dir,'directory',dirIdentity);return o.openSync(p,'wx',0o600);});
  if(opened.ok){fd=opened.value;acquired=true;attempt(prefix+'.write',()=>o.writeFileSync(fd,bytes));}
  if(acquired)attempt(prefix+'.close',()=>o.closeSync(fd));
 }
 let prepared,candidateIdentity,candidateBytes;
 if(errors.length===0){
  const encoded=attempt('candidate.prepare',()=>{
   const p=Object.freeze({args:s.args,started,ended,status:result.status,signal:result.signal,spawnError:null,stdoutSha256:stdoutHash,stderrSha256:stderrHash});
   const bytes=Buffer.from(JSON.stringify(p,null,2)+'\n');
   // Buffers are independent copies, not claimed to be deeply immutable.
   prepared=Object.freeze({p,stdout:Buffer.from(stdout),stderr:Buffer.from(stderr),capture:'COMPLETE_RAW_RECEIPT_ONLY'});return bytes;
  });
  if(encoded.ok){candidateBytes=encoded.value;persist('process-candidate.json',candidateBytes,'candidate');}
  if(errors.length===0)attempt('candidate.readback',()=>{
   candidateIdentity=identity(dir+'/process-candidate.json','file');const bytes=o.readFileSync(dir+'/process-candidate.json');assert(Buffer.isBuffer(bytes));assert(bytes.equals(candidateBytes),'Candidate bytes changed');
  });
 }
 if(errors.length===0){
  const final=attempt('publication.guard',()=>{
   o.pins();same(s.root,'directory',{dev:s.dev,ino:s.ino});same(dir,'directory',dirIdentity);same(dir+'/process-candidate.json','file',candidateIdentity);
   const bytes=o.readFileSync(dir+'/process-candidate.json');assert(Buffer.isBuffer(bytes)&&bytes.equals(candidateBytes),'Candidate bytes changed');absent(dir+'/process.json');
  });
  if(final.ok){
   try{o.linkSync(dir+'/process-candidate.json',dir+'/process.json');return prepared;}
   catch(cause){fail('publish',cause);}
  }
 }
 if(ownedDir){
  const diagnostic=attempt('incomplete.serialize',()=>{
   const record={status:'INCOMPLETE_RECORDER_CAPTURE_NOT_ACCEPTED',errors:errors.map((cause,i)=>({phase:phases[i],cause:describe(cause)})),streams:streams.map(x=>({name:x.name,acquired:x.acquired,...(x.hash===undefined?{}:{sha256:x.hash})}))};
   const encoded=o.serialize?o.serialize(record):JSON.stringify(record,null,2)+'\n';assert(typeof encoded==='string');return encoded;
  });
  if(diagnostic.ok)persist('recorder-incomplete.json',diagnostic.value,'incomplete');
 }
 const error=new AggregateError(errors,'Incomplete synchronous recorder capture');error.phases=phases;error.capture='INCOMPLETE';error.directory=ownedDir?dir:null;throw error;
}

import assert from 'node:assert/strict';import fs from 'node:fs';import os from 'node:os';import path from 'node:path';import {pathToFileURL} from 'node:url';import {fixture,sha} from './fixtures.mjs';
const modulePath=process.argv[2]??new URL('./recorder.mjs',import.meta.url).pathname;
const {recordSync}=await import(pathToFileURL(modulePath));
const events=[];let group;
function run(name,test){try{test();events.push({group,name,status:'PASS'});}catch(e){events.push({group,name,status:'FAIL',message:e.message,stack:e.stack});throw e;}}
function invoke(f,label='c'){return recordSync(f.owner,f.invocation,label,f.ops);}
function rejected(f,check=()=>{},label='c'){let caught=false,error;try{invoke(f,label);}catch(e){caught=true;error=e;}assert(caught);assert(!f.files.has('/owned/'+label+'/process.json'),'Incomplete capture published legacy receipt');check(error);return error;}
function traceHas(f,n){assert(f.trace.includes(n),'Missing '+n);}
try{
group=1;
run('complete schema, fixed dispatch, fd0 and publication last',()=>{const f=fixture(),r=invoke(f);assert.deepEqual(Object.keys(r.p).sort(),['args','started','ended','status','signal','spawnError','stdoutSha256','stderrSha256'].sort());assert.equal(r.p.status,0);assert.equal(r.p.stdoutSha256,sha(r.stdout));assert.equal(f.trace.at(-1),'link');assert.equal(f.fds.size,0);assert.equal(f.files.get('/owned/c/process.json'),f.files.get('/owned/c/process-candidate.json'));assert.equal(Object.isFrozen(r),true);});
for(const label of ['../escape','/absolute','a\\b','a//b'])run('unsafe label '+label,()=>{const f=fixture();rejected(f,()=>{},label);assert(!f.trace.includes('spawn'));});
for(const field of ['owner','invocation'])run('reject '+field+' proxy without traps',()=>{const f=fixture();let touched=false;f[field]=new Proxy(f[field],{get(){touched=true;throw Error('getter');},getOwnPropertyDescriptor(){touched=true;throw Error('descriptor');}});rejected(f);assert.equal(touched,false);assert.equal(f.trace.length,0);});
run('accessor invocation does not execute',()=>{const f=fixture();let calls=0;f.invocation=Object.freeze({get executable(){calls++;throw Error('get');},args:f.invocation.args});rejected(f);assert.equal(calls,0);});
run('wrong fixed environment blocks',()=>{const f=fixture();f.invocation=Object.freeze({...f.invocation,environment:Object.freeze({...f.invocation.environment,DOCKER_HOST:'wrong'})});rejected(f);assert(!f.trace.includes('spawn'));});
run('wrong ownership identity blocks',()=>{const f=fixture();f.owner=Object.freeze({...f.owner,ino:99});rejected(f);assert(!f.trace.includes('spawn'));});
run('no local publication support blocks',()=>{const f=fixture();f.ops.localExclusiveLink=false;rejected(f);assert(!f.trace.includes('spawn'));});
run('existing directory preserved',()=>{const f=fixture();f.dirs.set('/owned/c',{dev:1,ino:99});rejected(f);assert.equal(f.dirs.get('/owned/c').ino,99);assert(!f.trace.includes('spawn'));});
run('symlink/type check failure blocks',()=>{const f=fixture();f.ops.checked=()=>{throw Error('link');};rejected(f);assert(!f.trace.includes('spawn'));});
run('dependency pin failure blocks dispatch',()=>{const f=fixture(n=>{if(n==='pins')throw Error('pin');});rejected(f);assert(!f.trace.includes('spawn'));});
group=2;
run('second open closes stdout',()=>{const f=fixture(n=>{if(n==='open:stderr')throw Error('open');});rejected(f);traceHas(f,'close:stdout');assert(!f.trace.includes('spawn'));assert.equal(f.fds.size,0);});
run('first close still attempts second',()=>{const f=fixture(n=>{if(n==='close:stdout')throw Error('close');});rejected(f);traceHas(f,'close:stderr');assert.equal(f.trace.filter(x=>x==='close:stdout').length,1);});
for(const value of [undefined,null,false,0,'',new Error('primary'),new AggregateError([false],'nested')])run('spawn cause survives closes '+String(value),()=>{const f=fixture(n=>{if(n==='close:stdout'||n==='close:stderr')throw Error(n);});f.ops.spawnSync=()=>{throw value;};rejected(f,e=>{assert(e instanceof AggregateError);assert.equal(e.errors[0],value);assert.deepEqual(e.phases.slice(0,3),['dispatch','close.stdout','close.stderr']);});traceHas(f,'read:stdout');traceHas(f,'read:stderr');});
group=3;
run('stdout read fails independently',()=>{const f=fixture(n=>{if(n==='read:stdout')throw Error('read');});rejected(f);traceHas(f,'read:stderr');});
run('stdout hash fails independently',()=>{const f=fixture();f.ops.sha=bytes=>{if(bytes.length)throw Error('hash');return sha(bytes);};rejected(f);traceHas(f,'read:stderr');});
for(const clock of ['clock:0','clock:1'])run(clock+' failure owns cleanup',()=>{const f=fixture(n=>{if(n===clock)throw false;});rejected(f,e=>assert(e.errors.includes(false)));traceHas(f,'close:stdout');traceHas(f,'close:stderr');traceHas(f,'read:stdout');traceHas(f,'read:stderr');assert.equal(f.trace.includes('spawn'),clock==='clock:1');});
run('end clock preserves dispatch primary',()=>{const f=fixture(n=>{if(n==='clock:1')throw 'clock';});f.ops.spawnSync=()=>{throw null;};rejected(f,e=>{assert.equal(e.errors[0],null);assert.equal(e.errors[1],'clock');assert.deepEqual(e.phases.slice(0,2),['dispatch','clock.end']);});});
for(const value of [undefined,null,false,0,''])run('own result error '+String(value),()=>{const f=fixture();f.ops.spawnSync=()=>({status:0,signal:null,error:value});rejected(f,e=>assert.equal(e.errors[0],value));});
for(const result of [{signal:null},{status:0},{status:NaN,signal:null},{status:Infinity,signal:null},{status:0.5,signal:null},{status:null,signal:null},{status:0,signal:'SIGTERM'},null])run('malformed result '+JSON.stringify(result),()=>{const f=fixture();f.ops.spawnSync=()=>result;rejected(f);});
run('inherited result prototype rejected',()=>{const f=fixture();f.ops.spawnSync=()=>Object.assign(Object.create({error:false}),{status:0,signal:null});rejected(f);});
for(const key of ['error','status','signal'])run('result accessor '+key+' rejected uninvoked',()=>{const f=fixture();let touched=0;const r={status:0,signal:null};Object.defineProperty(r,key,{get(){touched++;throw Error('get');}});f.ops.spawnSync=()=>r;rejected(f);assert.equal(touched,0);});
run('result proxy rejected without traps',()=>{const f=fixture();let touched=0;f.ops.spawnSync=()=>new Proxy({status:0,signal:null},{get(){touched++;}});rejected(f);assert.equal(touched,0);});
for(const result of [{status:1,signal:null},{status:null,signal:'SIGTERM'}])run('truthful non-success result '+JSON.stringify(result),()=>{const f=fixture();f.ops.spawnSync=()=>result;const r=invoke(f);assert.equal(r.p.status,result.status);assert.equal(r.p.signal,result.signal);assert.equal(r.p.spawnError,null);});
group=4;
for(const phase of ['open:process-candidate.json','write:process-candidate.json','close:process-candidate.json','read:process-candidate.json'])run('candidate '+phase+' excludes complete reader path',()=>{const f=fixture(n=>{if(n===phase)throw Error(phase);});rejected(f);assert(!f.trace.includes('link'));});
run('candidate full write then throw stays unpublished',()=>{const f=fixture();const write=f.ops.writeFileSync;f.ops.writeFileSync=(fd,bytes)=>{write(fd,bytes);if(f.fds.get(fd)==='/owned/c/process-candidate.json')throw Error('after candidate write');};rejected(f);assert.equal(JSON.parse(f.files.get('/owned/c/process-candidate.json').bytes).status,0);traceHas(f,'close:process-candidate.json');});
run('candidate compare corruption rejected',()=>{const f=fixture();const read=f.ops.readFileSync;f.ops.readFileSync=p=>p.endsWith('/process-candidate.json')?Buffer.from('{}'):read(p);rejected(f);});
run('candidate and diagnostic close attempted after writes fail',()=>{const f=fixture(n=>{if(n==='write:process-candidate.json'||n==='write:recorder-incomplete.json')throw false;});rejected(f,e=>{assert.equal(e.errors[0],false);assert(e.phases.includes('incomplete.write'));});traceHas(f,'close:process-candidate.json');traceHas(f,'close:recorder-incomplete.json');});
group=5;
run('link before-effect failure preserves candidate',()=>{const f=fixture(n=>{if(n==='link')throw Error('link');});rejected(f,e=>assert(e.phases.includes('publish')));assert(f.files.has('/owned/c/process-candidate.json'));});
run('final pin drift rejects publication',()=>{let n=0;const f=fixture(x=>{if(x==='pins'&&++n===2)throw Error('drift');});rejected(f);assert(!f.trace.includes('link'));});
run('final candidate inode drift rejects',()=>{const f=fixture();const pins=f.ops.pins;let n=0;f.ops.pins=()=>{pins();if(++n===2)f.files.get('/owned/c/process-candidate.json').ino++;};rejected(f);assert(!f.trace.includes('link'));});
run('final byte drift rejects',()=>{const f=fixture();const pins=f.ops.pins;let n=0;f.ops.pins=()=>{pins();if(++n===2)f.files.get('/owned/c/process-candidate.json').bytes=Buffer.from('{}');};rejected(f);});
run('publication collision preserved and not attributed',()=>{const f=fixture();const link=f.ops.linkSync;f.ops.linkSync=(from,to)=>{f.files.set(to,{dev:1,ino:444,bytes:Buffer.from('PREEXISTING')});return link(from,to);};let e;try{invoke(f);}catch(x){e=x;}assert(e);assert.equal(f.files.get('/owned/c/process.json').bytes.toString(),'PREEXISTING');assert(e.phases.includes('publish'));});
group=6;
run('diagnostic errors preserve nested primary without getters',()=>{let got=0;const primary=new Error('original');Object.defineProperty(primary,'message',{get(){got++;throw Error('getter');}});const f=fixture(n=>{if(n==='write:recorder-incomplete.json')throw undefined;});f.ops.spawnSync=()=>{throw primary;};rejected(f,e=>{assert.equal(e.errors[0],primary);assert.equal(e.errors.at(-1),undefined);});assert.equal(got,0);});
run('opaque cyclic cause remains original',()=>{const primary={};primary.self=primary;const f=fixture();f.ops.spawnSync=()=>{throw primary;};rejected(f,e=>assert.equal(e.errors[0],primary));assert.equal(JSON.parse(f.files.get('/owned/c/recorder-incomplete.json').bytes).errors[0].cause.type,'opaque');});
run('diagnostic serialization failure remains secondary',()=>{const f=fixture();f.ops.spawnSync=()=>{throw false;};f.ops.serialize=()=>{throw null;};rejected(f,e=>{assert.equal(e.errors[0],false);assert.equal(e.errors.at(-1),null);assert.equal(e.phases.at(-1),'incomplete.serialize');});traceHas(f,'read:stdout');traceHas(f,'read:stderr');});
console.log(JSON.stringify({classification:'SYNTHETIC_SYSCALL_ACTUAL_FUNCTION_TESTS_HOST_ONLY',modulePath,groups:6,passed:events.length,events},null,2));
}catch(e){console.log(JSON.stringify({classification:'SYNTHETIC_SYSCALL_ACTUAL_FUNCTION_TEST_FAILURE',modulePath,events},null,2));process.exitCode=1;}

import assert from 'node:assert/strict';import crypto from 'node:crypto';import path from 'node:path';
export const sha=b=>crypto.createHash('sha256').update(b).digest('hex');
export function fixture(fault=()=>{}){
 const files=new Map(),dirs=new Map([['/owned',{dev:1,ino:1}]]),fds=new Map(),trace=[];let ino=2,fd=0,tick=0;
 const act=(name,...args)=>{trace.push(name);fault(name,...args);};
 const err=code=>Object.assign(new Error(code),{code});
 const stat=p=>{if(dirs.has(p))return{...dirs.get(p),isDirectory:()=>true,isFile:()=>false,isSymbolicLink:()=>false};if(files.has(p))return{...files.get(p),isDirectory:()=>false,isFile:()=>true,isSymbolicLink:()=>false};throw err('ENOENT');};
 const ops={
  checked(p,kind='file'){act('checked:'+p);const s=stat(p);assert(kind==='directory'?s.isDirectory():s.isFile());return p;},
  lstatSync(p){act('lstat:'+p);return stat(p);},
  mkdirSync(p){act('mkdir:'+p);if(dirs.has(p)||files.has(p))throw err('EEXIST');assert(dirs.has(path.dirname(p)));dirs.set(p,{dev:1,ino:ino++});},
  openSync(p,flag){act('open:'+path.basename(p));assert.equal(flag,'wx');if(files.has(p))throw err('EEXIST');files.set(p,{dev:1,ino:ino++,bytes:Buffer.alloc(0)});const n=fd++;fds.set(n,p);return n;},
  closeSync(n){act('close:'+path.basename(fds.get(n)));assert(fds.has(n));fds.delete(n);},
